import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;

public class HotelSearchService {
    private Connection connection;

    public HotelSearchService() throws Exception {
        Class.forName("com.mysql.jdbc.Driver");
        connection = DriverManager.getConnection(
                "jdbc:mysql://localhost:3306/hotels",
                "root",
                "password"
        );
    }

    public List<Hotel> searchHotelsByPrefix(String prefix) throws SQLException {
        PreparedStatement statement = connection.prepareStatement(
                "SELECT * FROM hotels WHERE name LIKE ?");
        statement.setString(1, "%" + prefix + "%");

        ResultSet resultSet = statement.executeQuery();
        List<Hotel> hotels = new ArrayList<>();
        while (resultSet.next()) {
            hotels.add(mapResultSetToHotel(resultSet));
        }
        return hotels;
    }

    private Hotel mapResultSetToHotel(ResultSet resultSet) throws SQLException {
        Hotel hotel = new Hotel();
        hotel.setId(resultSet.getInt("id"));
        hotel.setName(resultSet.getString("name"));

